**Converting facing pages in InDesign**

I need to convert a facing pages document to a non-facing single page using ExtendScript. It seems like I’ll need to set `documentPreferences.facingPages` to false and adjust the pages. The user wants to transform spreads with multiple master pages while keeping the layout intact. I should duplicate the document, create new pages sequentially, and ensure items crossing the spine are split. Finally, I’ll copy master pages and margins into the new document as needed.**Creating a new document in ExtendScript**

I'm working on a script in ExtendScript that creates a new document and duplicates master spreads from the source to the target. I'll map them by name and apply the same master to corresponding pages. I need to ensure that I maintain their relative positions while copying page items and account for locked or hidden items. Preserving section numbering might be important too! I'll optimize the script by disabling redraw and implementing error handling, with careful attention to measurement units and bleed settings. However, spread-spanning items won't split automatically, so I’ll mention that limitation.
[/Thinking]

```jsx
﻿/*  Convert a facing-pages (spreads) InDesign document into a single-page (non-facing)
    document while preserving:
      - page size / orientation / bleed / slug
      - per-page margins (copied to each resulting page)
      - page items geometry (duplicated onto corresponding pages)
      - master pages (all master spreads duplicated; pages keep same applied master by name)

    Notes / limitations:
      - Items that span across two pages in a spread (cross-spine objects) are duplicated as-is
        onto each page they belong to only if they are actually on that page. A single object
        that truly spans both pages (parent spread item) may not be representable on a non-facing
        page without manual adjustment.
      - Interactive elements, some plugin items, and certain non-pageItem structures may require
        manual checking after conversion.

    Usage:
      - Open the source document (spreads).
      - Run this script. It creates a NEW document (does not modify original).
*/

#target "InDesign"

(function () {
    if (app.documents.length === 0) {
        alert("Open a document first.");
        return;
    }

    var src = app.activeDocument;

    app.doScript(function () {
        var oldRedraw = app.scriptPreferences.enableRedraw;
        app.scriptPreferences.enableRedraw = false;

        // Keep units stable during geometry operations
        var oldHUnits = app.viewPreferences.horizontalMeasurementUnits;
        var oldVUnits = app.viewPreferences.verticalMeasurementUnits;
        app.viewPreferences.horizontalMeasurementUnits = MeasurementUnits.POINTS;
        app.viewPreferences.verticalMeasurementUnits = MeasurementUnits.POINTS;

        try {
            var dst = makeDestinationDocumentFromSource_(src);

            // Duplicate all master spreads first (so appliedMaster names can be preserved)
            var masterMap = duplicateMasters_(src, dst); // name -> dstMasterSpread

            // Copy sections (optional but helpful for page numbering)
            // (Sections are tied to pages; we'll re-create after pages exist.)

            // Build pages and copy content page-by-page
            var i, sp, p, srcPage, dstPage;

            // Ensure dst starts empty-ish: a new doc has at least one page.
            // We'll reuse the first page for the first source page, then add the rest.
            while (dst.pages.length > 1) dst.pages.lastItem().remove();

            for (i = 0; i < src.pages.length; i++) {
                srcPage = src.pages[i];

                if (i === 0) {
                    dstPage = dst.pages[0];
                } else {
                    dstPage = dst.pages.add(LocationOptions.AT_END);
                }

                // Copy per-page margins
                copyMargins_(srcPage, dstPage);

                // Apply the same master (by name) if possible
                applyMasterByName_(srcPage, dstPage, masterMap);

                // Copy page items on that page (not master items; those come from masters)
                duplicatePageItems_(srcPage, dstPage);

                // Copy page-level guides (page guides only; not spread guides)
                duplicatePageGuides_(srcPage, dstPage);
            }

            // Recreate sections (page numbering, prefixes)
            recreateSections_(src, dst);

            // Final: make sure destination is non-facing
            dst.documentPreferences.facingPages = false;

            alert("Done.\nCreated: " + dst.name);

        } catch (e) {
            alert("Error: " + e + "\n(Line " + (e.line || "?") + ")");
        } finally {
            app.viewPreferences.horizontalMeasurementUnits = oldHUnits;
            app.viewPreferences.verticalMeasurementUnits = oldVUnits;
            app.scriptPreferences.enableRedraw = oldRedraw;
        }
    }, ScriptLanguage.JAVASCRIPT, undefined, UndoModes.ENTIRE_SCRIPT, "Convert spreads doc to single-page doc");

    // -------- helpers --------

    function makeDestinationDocumentFromSource_(srcDoc) {
        // Create a new document matching key document preferences
        var dstDoc = app.documents.add();

        // Copy document preferences (safe subset)
        var sdp = srcDoc.documentPreferences;
        var ddp = dstDoc.documentPreferences;

        ddp.pageWidth  = sdp.pageWidth;
        ddp.pageHeight = sdp.pageHeight;
        ddp.pageOrientation = sdp.pageOrientation;

        ddp.facingPages = false; // target requirement
        ddp.pagesPerDocument = 1; // we'll add pages

        ddp.startPageNumber = sdp.startPageNumber;

        // Copy bleed / slug
        var sb = srcDoc.documentPreferences;
        dstDoc.documentPreferences.documentBleedTopOffset    = sb.documentBleedTopOffset;
        dstDoc.documentPreferences.documentBleedBottomOffset = sb.documentBleedBottomOffset;
        dstDoc.documentPreferences.documentBleedInsideOrLeftOffset  = sb.documentBleedInsideOrLeftOffset;
        dstDoc.documentPreferences.documentBleedOutsideOrRightOffset = sb.documentBleedOutsideOrRightOffset;
        dstDoc.documentPreferences.slugTopOffset    = sb.slugTopOffset;
        dstDoc.documentPreferences.slugBottomOffset = sb.slugBottomOffset;
        dstDoc.documentPreferences.slugInsideOrLeftOffset  = sb.slugInsideOrLeftOffset;
        dstDoc.documentPreferences.slugRightOrOutsideOffset = sb.slugRightOrOutsideOffset;

        // Copy intent / color settings that are often relevant
        dstDoc.documentColorSpace = srcDoc.documentColorSpace;
        dstDoc.transparencyPreferences.blendingSpace = srcDoc.transparencyPreferences.blendingSpace;

        // Copy layers (and their order/visibility/lock state)
        duplicateLayers_(srcDoc, dstDoc);

        return dstDoc;
    }

    function duplicateLayers_(srcDoc, dstDoc) {
        // Remove default layer(s) in destination only if we can safely rebuild
        // InDesign requires at least one layer, so we'll reuse the first and adjust.
        var i;

        // Ensure dst has same number of layers
        // First, rename/reconfigure the existing first layer to match src layer[0]
        var srcLayers = srcDoc.layers;
        if (srcLayers.length === 0) return;

        var dstFirst = dstDoc.layers[0];
        setLayerProps_(dstFirst, srcLayers[0]);

        // Add remaining layers
        for (i = 1; i < srcLayers.length; i++) {
            var newL = dstDoc.layers.add({ name: srcLayers[i].name });
            setLayerProps_(newL, srcLayers[i]);
        }

        // Reorder layers to match source (top-to-bottom)
        // InDesign layer index order is bottom-to-top, but move() makes it manageable.
        // We'll iterate from bottom to top, placing accordingly.
        for (i = 0; i < srcLayers.length; i++) {
            var sL = srcLayers[i];
            var dL = dstDoc.layers.itemByName(sL.name);
            if (dL.isValid) {
                dL.move(LocationOptions.AT_END); // end = top
            }
        }
        // Now rebuild correct stack: move in source order from bottom->top
        // Source layers[0] is bottom. We'll move each to beginning in sequence.
        for (i = srcLayers.length - 1; i >= 0; i--) {
            var dLi = dstDoc.layers.itemByName(srcLayers[i].name);
            if (dLi.isValid) dLi.move(LocationOptions.AT_BEGINNING);
        }
    }

    function setLayerProps_(dstLayer, srcLayer) {
        dstLayer.name = srcLayer.name;
        dstLayer.visible = srcLayer.visible;
        dstLayer.locked = srcLayer.locked;
        dstLayer.printable = srcLayer.printable;
    }

    function duplicateMasters_(srcDoc, dstDoc) {
        var map = {}; // master name -> dst masterSpread

        // Duplicate each master spread into destination.
        // This preserves master items and nested master references.
        for (var i = 0; i < srcDoc.masterSpreads.length; i++) {
            var srcMS = srcDoc.masterSpreads[i];

            // Skip "[None]" equivalent (InDesign uses appliedMaster = NothingEnum.NOTHING)
            // masterSpreads are actual masters; "[None]" isn't a masterSpread.
            var dup = srcMS.duplicate(LocationOptions.AT_END, dstDoc);

            // Ensure name matches (duplicate usually keeps it, but be explicit)
            try { dup.name = srcMS.name; } catch (_) {}

            map[srcMS.name] = dup;
        }

        return map;
    }

    function applyMasterByName_(srcPage, dstPage, masterMap) {
        // If source has no master, apply none
        if (srcPage.appliedMaster === NothingEnum.NOTHING) {
            dstPage.appliedMaster = NothingEnum.NOTHING;
            return;
        }

        var name = srcPage.appliedMaster.name;
        if (masterMap[name] && masterMap[name].isValid) {
            dstPage.appliedMaster = masterMap[name];
        } else {
            // fallback: try by name in destination
            var ms = dstPage.parent.masterSpreads.itemByName(name);
            dstPage.appliedMaster = (ms && ms.isValid) ? ms : NothingEnum.NOTHING;
        }
    }

    function copyMargins_(srcPage, dstPage) {
        var sm = srcPage.marginPreferences;
        var dm = dstPage.marginPreferences;

        // On a non-facing doc, inside/outside are still properties, but behave as left/right.
        dm.top    = sm.top;
        dm.bottom = sm.bottom;
        dm.left   = sm.left;
        dm.right  = sm.right;

        // Also copy margin columns/gutter if used
        dm.columnCount  = sm.columnCount;
        dm.columnGutter = sm.columnGutter;
    }

    function duplicatePageItems_(srcPage, dstPage) {
        // Duplicate only items that are actually on the page (not master page items).
        // This includes items on layers.
        var items = srcPage.pageItems;
        if (!items || items.length === 0) return;

        // Duplicate in reverse z-order to better preserve stacking (approximate)
        for (var i = items.length - 1; i >= 0; i--) {
            var it = items[i];

            // Skip master-derived items
            // (Master items usually have a parentPage but are on master; safest is to skip
            // items whose parent is a MasterSpread, but on pages it can be tricky.)
            // A reliable signal: if item is "isValid" and has "itemLayer", just duplicate.
            // However master page items will not be present in srcPage.pageItems anyway.
            try {
                it.duplicate(dstPage);
            } catch (e) {
                // Some items may fail duplication; ignore but continue
            }
        }
    }

    function duplicatePageGuides_(srcPage, dstPage) {
        // Copy page guides only (not spread guides).
        // InDesign guides live on spreads; page guides can be filtered by their fit to page bounds.
        // We'll copy guides whose guide parent is the spread AND whose location falls within page.
        var srcSpread = srcPage.parent;
        var dstSpread = dstPage.parent;

        if (!srcSpread.guides || srcSpread.guides.length === 0) return;

        var pb = srcPage.bounds; // [y1,x1,y2,x2]
        var top = pb[0], left = pb[1], bottom = pb[2], right = pb[3];

        for (var i = 0; i < srcSpread.guides.length; i++) {
            var g = srcSpread.guides[i];
            try {
                // Only duplicate guides that appear to belong to this page region
                if (g.orientation === HorizontalOrVertical.HORIZONTAL) {
                    if (g.location < top || g.location > bottom) continue;
                } else {
                    if (g.location < left || g.location > right) continue;
                }

                // Create guide on destination spread at same location
                dstSpread.guides.add(dstPage, {
                    orientation: g.orientation,
                    location: g.location,
                    guideType: g.guideType,
                    fitToPage: true
                });
            } catch (e) {
                // ignore
            }
        }
    }

    function recreateSections_(srcDoc, dstDoc) {
        // Remove default section(s) in destination
        // (There is always at least one section.)
        try {
            while (dstDoc.sections.length > 1) dstDoc.sections.lastItem().remove();
        } catch (_) {}

        // Recreate each source section at the equivalent page index
        for (var i = 0; i < srcDoc.sections.length; i++) {
            var ss = srcDoc.sections[i];
            var startIndex = ss.page.index; // page index in src

            if (startIndex < 0 || startIndex >= dstDoc.pages.length) continue;
            var dp = dstDoc.pages[startIndex];

            var ds;
            if (i === 0) {
                ds = dstDoc.sections[0];
                ds.page = dp;
            } else {
                ds = dstDoc.sections.add(dp);
            }

            // Copy key section settings
            ds.continueNumbering = ss.continueNumbering;
            ds.pageNumberStart = ss.pageNumberStart;
            ds.sectionPrefix = ss.sectionPrefix;
            ds.includeSectionPrefix = ss.includeSectionPrefix;
            ds.marker = ss.marker;

            try { ds.pageNumberStyle = ss.pageNumberStyle; } catch (_) {}
        }
    }

})();
